type artifactWhere[Q psql.Filterable] struct {
	cols        artifactColumns
	ID          psql.WhereMod[Q, string]
	CreatedAt   psql.WhereMod[Q, time.Time]
	WorkspaceID psql.WhereMod[Q, string]
	ItemID      psql.WhereMod[Q, string]
	OperationID psql.WhereNullMod[Q, string]
	InputKey    psql.WhereMod[Q, string]
	Sources     psql.WhereMod[Q, types.JSON[[]model.ArtifactSource]]
	ObjectKey   psql.WhereMod[Q, string]
	Filename    psql.WhereMod[Q, string]
	ContentType psql.WhereMod[Q, string]
	Size        psql.WhereMod[Q, int64]
	Sha256      psql.WhereMod[Q, string]
	Metrics     psql.WhereMod[Q, types.JSON[json.RawMessage]]
	ExpiresAt   psql.WhereMod[Q, time.Time]
	CreatedBy   psql.WhereMod[Q, string]
	R           artifactWhereR[Q]
}

func (artifactWhere[Q]) AliasedAs(alias string) artifactWhere[Q] {
	return buildArtifactWhere[Q](buildArtifactColumns(alias))
}

func buildArtifactWhere[Q psql.Filterable](cols artifactColumns) artifactWhere[Q] {
	return artifactWhere[Q]{
		cols:        cols,
		ID:          psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		WorkspaceID: psql.Where[Q, string](cols.WorkspaceID.Expression),
		ItemID:      psql.Where[Q, string](cols.ItemID.Expression),
		OperationID: psql.WhereNull[Q, string](cols.OperationID.Expression),
		InputKey:    psql.Where[Q, string](cols.InputKey.Expression),
		Sources:     psql.Where[Q, types.JSON[[]model.ArtifactSource]](cols.Sources.Expression),
		ObjectKey:   psql.Where[Q, string](cols.ObjectKey.Expression),
		Filename:    psql.Where[Q, string](cols.Filename.Expression),
		ContentType: psql.Where[Q, string](cols.ContentType.Expression),
		Size:        psql.Where[Q, int64](cols.Size.Expression),
		Sha256:      psql.Where[Q, string](cols.Sha256.Expression),
		Metrics:     psql.Where[Q, types.JSON[json.RawMessage]](cols.Metrics.Expression),
		ExpiresAt:   psql.Where[Q, time.Time](cols.ExpiresAt.Expression),
		CreatedBy:   psql.Where[Q, string](cols.CreatedBy.Expression),
		R:           artifactWhereR[Q]{cols: cols},
	}
}

// artifactWhereR holds the relationship-based filters of
// artifactWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type artifactWhereR[Q psql.Filterable] struct {
	cols artifactColumns
}

// HasItemResource filters parents that have a matching ItemResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w artifactWhereR[Q]) HasItemResource(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Resources.NameExpr()),
		sm.Where(Resources.Columns.ID.EQ(w.cols.ItemID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

